return items.map(item => {
  const input = item.json;

  const customFields = Array.isArray(input.custom_fields)
    ? input.custom_fields
    : [];

  const getField = (fieldName) => {
    return customFields.find(field => field.name === fieldName);
  };

  const getFieldValue = (fieldName) => {
    const field = getField(fieldName);

    if (!field) return null;

    if (field.type === 'drop_down' && field.type_config?.options) {
      const option = field.type_config.options.find(option => {
        return String(option.id) === String(field.value);
      });

      return option ? option.name : field.value;
    }

    return field.value ?? null;
  };

  const taskId = input.id;
  const subject = input.name || '';
  const message = input.description || '';

  const requesterName = getFieldValue('Requester Name');
  const requesterEmail = getFieldValue('Requester Email');
  const requesterCompany = getFieldValue('Company');
  const product = getFieldValue('Product');

  const text = `${subject} ${message}`.toLowerCase();

  let category = 'general';

  if (/(payment|invoice|refund|subscription|charge|billing)/i.test(text)) {
    category = 'billing';
  } else if (/(bug|error|crash|api|webhook|integration|technical|production down)/i.test(text)) {
    category = 'technical';
  } else if (/(login|password|access|permission|account)/i.test(text)) {
    category = 'account';
  } else if (/(feature|request|improvement|would like)/i.test(text)) {
    category = 'feature_request';
  }

  let priority = 'medium';

  if (/(production down|data loss|cannot access|payment blocked|urgent)/i.test(text)) {
    priority = 'urgent';
  } else if (/(payment|invoice|api failing|major bug|refund|blocked)/i.test(text)) {
    priority = 'high';
  } else if (category === 'feature_request') {
    priority = 'low';
  }

  const validationErrors = [
    !taskId ? 'missing_task_id' : null,
    !requesterEmail ? 'missing_requester_email' : null,
    !subject ? 'missing_subject' : null,
    !message ? 'missing_message' : null
  ].filter(Boolean);

  return {
    json: {
      external_id: taskId,
      event_source: 'clickup_support_form',

      clickup_task_id: taskId,
      clickup_task_url: input.url || input.task_url || null,

      requester_name: requesterName,
      requester_email: requesterEmail
        ? String(requesterEmail).toLowerCase().trim()
        : null,
      requester_company: requesterCompany,

      subject,
      message,
      product,

      category,
      priority,

      is_valid: validationErrors.length === 0,
      validation_errors: validationErrors,

      raw_clickup_payload: input
    }
  };
});

